import random, math, importlib, sched
class Env:
    def __init__(s, switch, jump, growth, seed):
        s.n_segments=40; s.b_min=4; s.b_max=8192; s.t_overhead=0.962; s.throughput=475
        s.switch=switch; s.jump=jump; s.growth=growth; s.rng=random.Random(seed); s.i=0; s.t=0; s.calls=0
    def bc(s,i):
        if i<s.switch: return 35+3.2*i
        return s.jump*(1+s.growth*(i-s.switch))
    def run_segment(s,b):
        assert s.b_min<=b<=s.b_max and s.i<40
        st=0.0242*(1+s.bc(s.i)/b)*s.rng.gauss(1,0.05)
        t=st*(s.t_overhead+b/s.throughput); s.t+=t; s.i+=1
        return {'segment':s.i-1,'batch':b,'steps':st,'seconds':t,'segments_left':40-s.i,'done':s.i==40}
    def elapsed(s): return s.t
def const(env,b):
    for _ in range(40): env.run_segment(b)
